/// Global combat tuning, verbatim from `CombatParameters`,
/// `PlayerCombatParameters` and `PvpParameters`.
///
/// Every constant carries the struct it came from so a reader can go back to
/// the asset. Values are `f32` because the client stores them as `float`.
pub mod combat_params {
    // ---- CombatParameters: damage reduction ----
    /// Damage reduction per point of Armor Rating (physical only).
    pub const REDUCTION_PER_ARMOR_RATING: f32 = 0.1_f32;
    /// Hard cap on armor-sourced damage reduction.
    pub const MAXIMUM_ARMOR_REDUCTION: f32 = 0.95_f32;
    /// Damage reduction per point of Resistance Rating.
    pub const REDUCTION_PER_RESISTANCE_RATING: f32 = 1.0_f32;
    /// Hard cap on resistance-sourced damage reduction.
    pub const MAXIMUM_RESISTANCE_REDUCTION: f32 = 0.95_f32;
    /// Damage reduction per point of Block Rating.
    pub const REDUCTION_PER_BLOCK_RATING: f32 = 0.1_f32;
    /// Block-rating multiplier against physical damage types.
    pub const PHYSICAL_BLOCK_RATING_FACTOR: f32 = 1.0_f32;
    /// Block-rating multiplier against elemental damage types (blocking is
    /// deliberately weaker vs elements).
    pub const ELEMENTAL_BLOCK_RATING_FACTOR: f32 = 0.6666667_f32;
    /// Hard cap on block-sourced damage reduction.
    pub const MAXIMUM_BLOCK_REDUCTION: f32 = 0.95_f32;
    /// Floor on block-sourced damage reduction.
    pub const MINIMUM_BLOCK_REDUCTION: f32 = 0.0_f32;
    /// Increase in damage taken per point of Weakness Rating.
    pub const INCREASE_PER_WEAKNESS_RATING: f32 = 1.0_f32;
    /// Hard cap on the weakness damage increase.
    pub const MAXIMUM_WEAKNESS_EFFECT: f32 = 1.0_f32;
    /// Damage increase per point of Weapon Rating.
    pub const REDUCTION_PER_WEAPON_RATING: f32 = 0.01_f32;
    /// Blockability used when an attack does not specify one.
    pub const DEFAULT_BLOCKABILITY: f32 = 1.0_f32;

    // ---- CombatParameters: continuous (damage-over-time) effectiveness ----
    /// Multiplier applied to Absorb when the incoming damage is continuous.
    pub const CONTINUOUS_DAMAGE_ABSORB_EFFECTIVENESS: f32 = 0.75_f32;
    /// Multiplier applied to Blocking against continuous damage.
    ///
    /// **Note:** this one is `1`, not `0.75` — blocking is *not* de-rated
    /// against DoT, unlike absorb/fortify/resistance/revenge/weakness.
    pub const CONTINUOUS_DAMAGE_BLOCKING_EFFECTIVENESS: f32 = 1.0_f32;
    /// Multiplier applied to Fortify against continuous damage.
    pub const CONTINUOUS_DAMAGE_FORTIFY_EFFECTIVENESS: f32 = 0.75_f32;
    /// Multiplier applied to Resistance against continuous damage.
    pub const CONTINUOUS_DAMAGE_RESISTANCE_EFFECTIVENESS: f32 = 0.75_f32;
    /// Multiplier applied to Revenge against continuous damage.
    pub const CONTINUOUS_DAMAGE_REVENGE_EFFECTIVENESS: f32 = 0.75_f32;
    /// Multiplier applied to Weakness against continuous damage.
    pub const CONTINUOUS_DAMAGE_WEAKNESS_EFFECTIVENESS: f32 = 0.75_f32;
    /// Multiplier applied to Fortify against continuous *healing*.
    pub const CONTINUOUS_HEALING_FORTIFY_EFFECTIVENESS: f32 = 0.4_f32;

    // ---- CombatParameters: timing / thresholds ----
    /// Base stagger duration, seconds.
    pub const BASE_STAGGER_DURATION: f32 = 1.5_f32;
    /// Health percentage (0..100) below which the fighter is "critical".
    pub const CRITICAL_HEALTH_THRESHOLD: f32 = 35.0_f32;
    /// Sliding window, in seconds, over which damage instances accumulate for
    /// the elemental status-effect trigger.
    pub const DAMAGE_INSTANCE_WINDOW: f32 = 5.0_f32;
    /// PvE simulation tick, seconds.
    pub const GLOBAL_TICK_INTERVAL: f32 = 0.1_f32;
    /// **PvP** simulation tick, seconds — the arena rate.
    pub const GLOBAL_PVP_TICK_INTERVAL: f32 = 0.2_f32;
    /// Frost damage is mirrored into Stamina damage at this ratio.
    pub const FROST_DAMAGE_TO_STAMINA_DAMAGE: f32 = 1.0_f32;
    /// Shock damage is mirrored into Magicka damage at this ratio.
    pub const SHOCK_DAMAGE_TO_MAGICKA_DAMAGE: f32 = 1.0_f32;
    /// Fraction of max health ravaged by the Poisoned status.
    pub const POISONED_RAVAGE_HEALTH_PERCENT: f32 = 0.2_f32;
    /// Movement-speed multiplier while Slowed.
    pub const SLOW_STATUS_MULTIPLIER: f32 = 0.75_f32;
    /// Seconds of no-combat before the combat state ends.
    pub const END_COMBAT_TIME: f32 = 0.2_f32;
    /// Seconds of no-combat before the encounter ends.
    pub const END_ENCOUNTER_TIME: f32 = 0.2_f32;
    /// Resistance fraction above which the client shows a "Resisted" popup.
    pub const RESIST_MESSAGING_THRESHOLD: f32 = 0.2_f32;
    /// Shield enchantments are ignored while block rating is low.
    pub const IGNORE_SHIELD_ENCHANTS_ON_LOW_BLOCK: bool = true;
    /// Optimal-block state is reset when block rating drops low.
    pub const RESET_OPTIMAL_BLOCK_ON_LOW_BLOCK: bool = true;

    // ---- PlayerCombatParameters ----
    /// Floor on a weapon's attack delay, seconds.
    pub const GLOBAL_MINIMUM_ATTACK_DELAY: f32 = 0.1_f32;
    /// Seconds after an optimal block before the optimal-block window resets.
    pub const POST_OPTIMAL_BLOCK_RESET_TIME: f32 = 1.4_f32;
    /// Seconds from idle to a fully charged attack.
    pub const IDLE_TO_CHARGE_TIME: f32 = 0.4_f32;
    /// Minimum time an attack stays in the attack state, seconds.
    pub const ATTACK_STATE_MINIMUM_TIME: f32 = 0.15_f32;
    /// Auto-attack speed for the weapon.
    pub const WEAPON_AUTO_ATTACK_SPEED: f32 = 10.0_f32;

    // ---- PvpParameters ----
    /// Consumables a fighter may use per arena round.
    pub const CONSUMABLES_PER_ROUND: u32 = 1;
    /// Charge-animation speed modifier in PvP.
    pub const CHARGE_ANIM_MODIFIER: f32 = 0.3_f32;
    /// Spawn separation between the two fighters, metres.
    pub const OPPONENT_SPAWN_DISTANCE: f32 = 2.4_f32;
    /// Server-side hit registration delay, seconds.
    pub const SERVER_HIT_TIME: f32 = 0.04_f32;

    // ---- CombatParameters.elemental_status_data ----
    // status_type: 4 = Fire, 5 = Frost, 6 = Shock, 7 = Poison.
    /// Fraction of the *damage window* total, relative to max health, that
    /// triggers the elemental status (same 0.25 for all four elements).
    pub const HEALTH_PERCENT_TO_CAUSE_STATUS: f32 = 0.25_f32;
    /// Duration of an elemental status effect, seconds (same 5 for all four).
    pub const ELEMENTAL_STATUS_DURATION: f32 = 5.0_f32;
    /// Per-tick percent-of-max-health damage dealt by the Fire status.
    pub const FIRE_PCT_HEALTH: f32 = 0.02_f32;
    /// Per-tick percent-of-max-health damage dealt by the Frost status.
    ///
    /// **Zero in the shipped data** — Frost applies its
    /// secondary stamina drain, not a
    /// damage-over-time. Any nonzero DoT here is a model bug.
    pub const FROST_PCT_HEALTH: f32 = 0.0_f32;
    /// Per-tick percent-of-max-health damage dealt by the Shock status.
    ///
    /// **Zero in the shipped data** — Shock applies its
    /// secondary magicka drain, not a
    /// damage-over-time. Any nonzero DoT here is a model bug.
    pub const SHOCK_PCT_HEALTH: f32 = 0.0_f32;
    /// Per-tick percent-of-max-health damage dealt by the Poison status.
    pub const POISON_PCT_HEALTH: f32 = 0.02_f32;

    /// One row of `CombatParameters.elemental_status_data`.
    #[derive(Debug, Clone, Copy, PartialEq)]
    pub struct ElementalStatus {
        /// 4 = Fire, 5 = Frost, 6 = Shock, 7 = Poison.
        pub status_type: u8,
        /// Damage type that accumulates toward this status.
        pub source_damage: u8,
        /// Status duration, seconds.
        pub duration: f32,
        /// Fraction of max health, within `DAMAGE_INSTANCE_WINDOW`, to trigger.
        pub health_percent_to_cause_status: f32,
        /// Per-tick fraction of max health dealt while the status is active.
        pub percent_health_damage: f32,
    }

    /// The four elemental statuses, ordered Fire, Frost, Shock, Poison.
    pub const ELEMENTAL_STATUSES: [ElementalStatus; 4] = [
        ElementalStatus {
            status_type: 4,
            source_damage: 4,
            duration: 5.0_f32,
            health_percent_to_cause_status: 0.25_f32,
            percent_health_damage: 0.02_f32,
        },
        ElementalStatus {
            status_type: 5,
            source_damage: 5,
            duration: 5.0_f32,
            health_percent_to_cause_status: 0.25_f32,
            percent_health_damage: 0.0_f32,
        },
        ElementalStatus {
            status_type: 6,
            source_damage: 6,
            duration: 5.0_f32,
            health_percent_to_cause_status: 0.25_f32,
            percent_health_damage: 0.0_f32,
        },
        ElementalStatus {
            status_type: 7,
            source_damage: 7,
            duration: 5.0_f32,
            health_percent_to_cause_status: 0.25_f32,
            percent_health_damage: 0.02_f32,
        },
    ];

    /// Look up the elemental status row for a `status_type` (4..=7).
    pub fn elemental_status(status_type: u8) -> Option<&'static ElementalStatus> {
        ELEMENTAL_STATUSES.iter().find(|e| e.status_type == status_type)
    }
}

/// Damage type as the client enumerates it.
///
/// 1..=3 are the physical types (`UI.Help.DamageTypes.Description`: daggers
/// and swords slash, axes cleave, hammers and maces bash); 4..=7 are the
/// elemental types that drive `CombatParameters.elemental_status_data`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum DamageType {
    /// `0`
    None = 0,
    /// `1`
    Slashing = 1,
    /// `2`
    Cleaving = 2,
    /// `3`
    Bashing = 3,
    /// `4`
    Fire = 4,
    /// `5`
    Frost = 5,
    /// `6`
    Shock = 6,
    /// `7`
    Poison = 7,
}

impl DamageType {
    /// Parse the raw client enum value.
    pub const fn from_raw(v: u8) -> Option<Self> {
        match v {
            0 => Some(Self::None),
            1 => Some(Self::Slashing),
            2 => Some(Self::Cleaving),
            3 => Some(Self::Bashing),
            4 => Some(Self::Fire),
            5 => Some(Self::Frost),
            6 => Some(Self::Shock),
            7 => Some(Self::Poison),
            _ => None,
        }
    }
    /// The raw client enum value.
    pub const fn raw(self) -> u8 {
        self as u8
    }
    /// True for Slashing / Cleaving / Bashing — the types Armor Rating reduces.
    pub const fn is_physical(self) -> bool {
        matches!(self, Self::Slashing | Self::Cleaving | Self::Bashing)
    }
    /// True for Fire / Frost / Shock / Poison.
    pub const fn is_elemental(self) -> bool {
        matches!(self, Self::Fire | Self::Frost | Self::Shock | Self::Poison)
    }
}

/// Weapon handling class (`UI.Item.WeaponClass.{Light,Balanced,Heavy}`).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum WeaponClass {
    /// `1`
    Light = 1,
    /// `2`
    Versatile = 2,
    /// `3`
    Heavy = 3,
}

impl WeaponClass {
    /// Parse the raw client enum value.
    pub const fn from_raw(v: u8) -> Option<Self> {
        match v {
            1 => Some(Self::Light),
            2 => Some(Self::Versatile),
            3 => Some(Self::Heavy),
            _ => None,
        }
    }
    /// The raw client enum value.
    pub const fn raw(self) -> u8 {
        self as u8
    }
}

/// Weapon family (the nine template shapes in `WeaponTemplateList`).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum WeaponType {
    /// `1`
    Dagger = 1,
    /// `2`
    HandAxe = 2,
    /// `3`
    LightHammer = 3,
    /// `4`
    Longsword = 4,
    /// `5`
    WarAxe = 5,
    /// `6`
    Mace = 6,
    /// `7`
    Greatsword = 7,
    /// `8`
    Battleaxe = 8,
    /// `9`
    Warhammer = 9,
}

impl WeaponType {
    /// Parse the raw client enum value.
    pub const fn from_raw(v: u8) -> Option<Self> {
        match v {
            1 => Some(Self::Dagger),
            2 => Some(Self::HandAxe),
            3 => Some(Self::LightHammer),
            4 => Some(Self::Longsword),
            5 => Some(Self::WarAxe),
            6 => Some(Self::Mace),
            7 => Some(Self::Greatsword),
            8 => Some(Self::Battleaxe),
            9 => Some(Self::Warhammer),
            _ => None,
        }
    }
    /// The raw client enum value.
    pub const fn raw(self) -> u8 {
        self as u8
    }
}

/// Per-template weapon stats from `WeaponTemplateList`.
///
/// `base_damage` is the one-handed figure; `base_two_handed_damage` is what
/// applies when the same template is wielded two-handed (they are equal for
/// most templates). `attack_delay` is floored by
/// [`combat_params::GLOBAL_MINIMUM_ATTACK_DELAY`].
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct WeaponStats {
    /// Item template UUID (what a character's equipment references).
    pub uuid: &'static str,
    /// English display name.
    pub name: &'static str,
    /// One-handed base damage.
    pub base_damage: f32,
    /// Two-handed base damage.
    pub base_two_handed_damage: f32,
    /// Seconds between swings.
    pub attack_delay: f32,
    /// Seconds of post-swing recovery.
    pub recovery_time: f32,
    /// Block Rating contributed while blocking with this weapon.
    pub block_base: f32,
    /// Multiplier applied to `block_base` on an optimal block.
    pub optimal_block_boost: f32,
    /// Physical damage type this template deals.
    pub damage_type: DamageType,
    /// Light / Versatile / Heavy.
    pub weapon_class: WeaponClass,
    /// Dagger / HandAxe / … / Warhammer.
    pub weapon_type: WeaponType,
    /// Character level required to equip.
    pub required_level: u16,
    /// Item tier (1..=10, smithy material tier).
    pub tier: u8,
    /// Properties the TEMPLATE always carries: `(property_uuid, tier)`.
    ///
    /// Artifact effects live here rather than in the item instance's
    /// `properties.ENCHANTING`, which is `null` on every captured artifact — so
    /// dropping this field made all 24 artifacts pure stat-sticks. Ebony Mail's
    /// poison aura, Dawnbreaker's fire damage and EDIR, Dragon's Blight's
    /// armour piercing all arrive through here or not at all.
    pub mandatory_properties: &'static [(&'static str, u8)],
}

