/// The `_parameters` block carried by maneuver ranks (animation + the
/// one/two-handed damage multipliers the maneuver applies).
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct ManeuverParams {
    /// Animation id (raw client enum).
    pub animation: i32,
    /// Flat bonus damage added by the maneuver.
    pub bonus_damage: f32,
    /// Damage multiplier when one-handed.
    pub one_handed_multiplier: f32,
    /// Damage multiplier when two-handed.
    pub two_handed_multiplier: f32,
    /// Which side the maneuver is active on (raw client enum).
    pub active_side: i32,
}

/// One rank of one ability, verbatim from its `<Name>Rank<N>.asset`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct AbilityRank {
    /// UUID of the owning ability (see [`Ability::uuid`]).
    pub ability_uuid: &'static str,
    /// 1-based rank number.
    pub rank: u16,
    /// Source asset name, e.g. `WardRank1` — the provenance of every number here.
    pub asset: &'static str,
    /// Hero level needed to buy this rank; `-1` = not purchasable.
    pub required_hero_level: i32,
    /// Ability points to buy this rank; `-1` = not purchasable.
    pub ability_point_cost: i32,
    /// Stamina cost. `None` on perk ranks, which have no activation.
    pub stamina_cost: Option<f32>,
    /// Magicka cost. `None` on perk ranks.
    pub magicka_cost: Option<f32>,
    /// Cooldown, seconds. `None` on perk ranks.
    pub cooldown: Option<f32>,
    /// Cooldown charged at the start of a fight, seconds. `None` on perk ranks.
    pub initial_cooldown: Option<f32>,
    /// Power level (scales with the rank's hero level). `None` on perk ranks.
    pub power_level: Option<i32>,
    /// Whether the ability can be cast out of combat. `None` on perk ranks.
    pub can_be_cast_out_of_combat: Option<bool>,
    /// Sparse subclass fields, **sorted by [`AbilityField`]**. Read with
    /// [`AbilityRank::get`] or the named accessors.
    pub effects: &'static [(AbilityField, f32)],
    /// Damage types this rank grants resistance to (`4..=7` = fire/frost/shock/poison).
    pub resistances_to_add: &'static [i32],
    /// Status effects this rank removes.
    pub statuses_to_remove: &'static [i32],
    /// Damage types this rank's resistance bonus applies to.
    pub resist_types: &'static [i32],
    /// Damage types the target becomes vulnerable to.
    pub vulnerable_damage_types: &'static [i32],
    /// Equipment slots the rank inspects (Matching Set).
    pub slots_to_check: &'static [i32],
    /// Per-weapon-class bonus damage, `(weapon_class_raw, value)`.
    pub bonus_damages: &'static [(u8, f32)],
    /// Maneuver animation/multiplier block, when this is a maneuver rank.
    pub parameters: Option<ManeuverParams>,
    /// UUID of the ward this rank refreshes (Ward-linked ranks only).
    pub ward_uid: Option<&'static str>,
}

impl AbilityRank {
    /// Look up one sparse subclass field. `None` = the shipped asset does not
    /// define it for this rank (which is *not* the same as zero).
    pub fn get(&self, field: AbilityField) -> Option<f32> {
        self.effects
            .binary_search_by(|(f, _)| f.cmp(&field))
            .ok()
            .map(|i| self.effects[i].1)
    }
    #[doc = "Direct hit damage. Shortcut for [`AbilityField::Damage`]."]
    pub fn damage(&self) -> Option<f32> {
        self.get(AbilityField::Damage)
    }
    #[doc = "Damage-over-time rate. Shortcut for [`AbilityField::DamagePerSecond`]."]
    pub fn damage_per_second(&self) -> Option<f32> {
        self.get(AbilityField::DamagePerSecond)
    }
    #[doc = "Effect duration, seconds. Shortcut for [`AbilityField::Duration`]."]
    pub fn duration(&self) -> Option<f32> {
        self.get(AbilityField::Duration)
    }
    #[doc = "Cast/channel time, seconds. Shortcut for [`AbilityField::ChannelDuration`]."]
    pub fn channel_duration(&self) -> Option<f32> {
        self.get(AbilityField::ChannelDuration)
    }
    #[doc = "Projectile speed. Shortcut for [`AbilityField::ProjectileSpeed`]."]
    pub fn projectile_speed(&self) -> Option<f32> {
        self.get(AbilityField::ProjectileSpeed)
    }
    #[doc = "Ward hit points absorbed. Shortcut for [`AbilityField::WardHealth`]."]
    pub fn ward_health(&self) -> Option<f32> {
        self.get(AbilityField::WardHealth)
    }
    #[doc = "Armor Rating granted by the ward. Shortcut for [`AbilityField::WardArmor`]."]
    pub fn ward_armor(&self) -> Option<f32> {
        self.get(AbilityField::WardArmor)
    }
    #[doc = "Ward duration, seconds. Shortcut for [`AbilityField::WardDuration`]."]
    pub fn ward_duration(&self) -> Option<f32> {
        self.get(AbilityField::WardDuration)
    }
    #[doc = "Damage that must land to trigger Paralyze. Shortcut for [`AbilityField::DamageToCauseParalyze`]."]
    pub fn damage_to_cause_paralyze(&self) -> Option<f32> {
        self.get(AbilityField::DamageToCauseParalyze)
    }
    #[doc = "Damage that must land to trigger Stagger. Shortcut for [`AbilityField::DamageToCauseStagger`]."]
    pub fn damage_to_cause_stagger(&self) -> Option<f32> {
        self.get(AbilityField::DamageToCauseStagger)
    }
    #[doc = "Damage that must land to trigger Blind. Shortcut for [`AbilityField::DamageToCauseBlind`]."]
    pub fn damage_to_cause_blind(&self) -> Option<f32> {
        self.get(AbilityField::DamageToCauseBlind)
    }
    #[doc = "Resistance Rating granted. Shortcut for [`AbilityField::ResistanceAmount`]."]
    pub fn resistance_amount(&self) -> Option<f32> {
        self.get(AbilityField::ResistanceAmount)
    }
    #[doc = "Resistance duration, seconds. Shortcut for [`AbilityField::ResistanceDuration`]."]
    pub fn resistance_duration(&self) -> Option<f32> {
        self.get(AbilityField::ResistanceDuration)
    }
    #[doc = "Shield hit points granted. Shortcut for [`AbilityField::ShieldHealth`]."]
    pub fn shield_health(&self) -> Option<f32> {
        self.get(AbilityField::ShieldHealth)
    }
    #[doc = "Stun duration, seconds. Shortcut for [`AbilityField::StunDuration`]."]
    pub fn stun_duration(&self) -> Option<f32> {
        self.get(AbilityField::StunDuration)
    }
    #[doc = "Paralyze duration, seconds. Shortcut for [`AbilityField::ParalyzeDuration`]."]
    pub fn paralyze_duration(&self) -> Option<f32> {
        self.get(AbilityField::ParalyzeDuration)
    }
    #[doc = "Freeze duration, seconds. Shortcut for [`AbilityField::FreezeDuration`]."]
    pub fn freeze_duration(&self) -> Option<f32> {
        self.get(AbilityField::FreezeDuration)
    }
    #[doc = "Forced-block duration, seconds. Shortcut for [`AbilityField::BlockDuration`]."]
    pub fn block_duration(&self) -> Option<f32> {
        self.get(AbilityField::BlockDuration)
    }
    #[doc = "Armor Rating ignored. Shortcut for [`AbilityField::ArmorPiercingPercent`]."]
    pub fn armor_piercing_percent(&self) -> Option<f32> {
        self.get(AbilityField::ArmorPiercingPercent)
    }
    #[doc = "Block Rating ignored. Shortcut for [`AbilityField::BlockPiercingPercent`]."]
    pub fn block_piercing_percent(&self) -> Option<f32> {
        self.get(AbilityField::BlockPiercingPercent)
    }
    #[doc = "Elemental resistance ignored. Shortcut for [`AbilityField::ElementalResistancePiercing`]."]
    pub fn elemental_resistance_piercing(&self) -> Option<f32> {
        self.get(AbilityField::ElementalResistancePiercing)
    }
    #[doc = "Elemental block rating ignored. Shortcut for [`AbilityField::ElementalBlockPiercing`]."]
    pub fn elemental_block_piercing(&self) -> Option<f32> {
        self.get(AbilityField::ElementalBlockPiercing)
    }
    #[doc = "Flat damage reduction granted. Shortcut for [`AbilityField::DamageReduction`]."]
    pub fn damage_reduction(&self) -> Option<f32> {
        self.get(AbilityField::DamageReduction)
    }
    #[doc = "Damage cap on a dodge. Shortcut for [`AbilityField::MaximumDamageDodged`]."]
    pub fn maximum_damage_dodged(&self) -> Option<f32> {
        self.get(AbilityField::MaximumDamageDodged)
    }
    #[doc = "Damage cap on an absorb. Shortcut for [`AbilityField::MaximumAmountAbsorbed`]."]
    pub fn maximum_amount_absorbed(&self) -> Option<f32> {
        self.get(AbilityField::MaximumAmountAbsorbed)
    }
}

/// Ability type as the client enumerates it.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum AbilityKind {
    /// Magicka-cost spell.
    Spell,
    /// Stamina-cost maneuver.
    Maneuver,
    /// Passive perk.
    Perk,
}

/// One learnable ability, from `LearnableAbilityList`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Ability {
    /// Ability UUID — what a character's `equippedAbilities` / `abilities` map uses.
    pub uuid: &'static str,
    /// English display name.
    pub name: &'static str,
    /// Editor name, e.g. `Ward` — matches the `<Name>Rank<N>` asset prefix.
    pub editor_name: &'static str,
    /// Spell / Maneuver / Perk.
    pub kind: AbilityKind,
    /// Damage type the ability deals, if any.
    pub damage_type: Option<DamageType>,
    /// Highest rank that exists (including bonus ranks from gear).
    pub maximum_level: u16,
    /// Highest rank buyable with ability points.
    pub maximum_purchaseable_level: u16,
    /// Ability tier.
    pub tier: u8,
    /// Whether the ability only ever appears on enemies.
    pub enemy_only: bool,
    /// Whether the ability boosts damage (drives client damage-preview UI).
    pub is_damage_boosting: bool,
    /// Index of this ability's first rank in [`ABILITY_RANKS`].
    pub ranks_start: u16,
    /// Number of ranks in [`ABILITY_RANKS`] belonging to this ability.
    pub ranks_len: u16,
}

impl Ability {
    /// All ranks of this ability, ordered by rank number.
    pub fn ranks(&self) -> &'static [AbilityRank] {
        let s = self.ranks_start as usize;
        &ABILITY_RANKS[s..s + self.ranks_len as usize]
    }
}

