// ------------------------------------------------------------------ lookups

/// Weapon stats for an item template UUID.
pub fn weapon(template_uuid: &str) -> Option<&'static WeaponStats> {
    WEAPONS
        .binary_search_by(|w| w.uuid.cmp(template_uuid))
        .ok()
        .map(|i| &WEAPONS[i])
}

/// Armor stats for an item template UUID.
/// The TEMPLATE's always-on properties, whichever kind of item it is.
///
/// Empty for the overwhelming majority; non-empty for the 165 templates that carry
/// them, which is where every artifact effect lives.
pub fn mandatory_properties(template_uuid: &str) -> &'static [(&'static str, u8)] {
    if let Some(w) = weapon(template_uuid) {
        return w.mandatory_properties;
    }
    if let Some(a) = armor(template_uuid) {
        return a.mandatory_properties;
    }
    if let Some(s) = shield(template_uuid) {
        return s.mandatory_properties;
    }
    &[]
}

pub fn armor(template_uuid: &str) -> Option<&'static ArmorStats> {
    ARMORS
        .binary_search_by(|a| a.uuid.cmp(template_uuid))
        .ok()
        .map(|i| &ARMORS[i])
}

/// Armor Rating for an item template UUID. `None` for anything that is not
/// an armor template (rings, necklaces, weapons, …).
pub fn armor_rating(template_uuid: &str) -> Option<f32> {
    armor(template_uuid).map(|a| a.armor_rating)
}

/// Shield stats for an item template UUID.
pub fn shield(template_uuid: &str) -> Option<&'static ShieldStats> {
    SHIELDS
        .binary_search_by(|s| s.uuid.cmp(template_uuid))
        .ok()
        .map(|i| &SHIELDS[i])
}

/// The Block Rating an equipped template contributes, whether it is a weapon
/// or a shield.
pub fn block_base(template_uuid: &str) -> Option<f32> {
    weapon(template_uuid)
        .map(|w| w.block_base)
        .or_else(|| shield(template_uuid).map(|s| s.block_base))
}

/// Ability definition for an ability UUID.
pub fn ability(ability_uuid: &str) -> Option<&'static Ability> {
    ABILITIES
        .binary_search_by(|a| a.uuid.cmp(ability_uuid))
        .ok()
        .map(|i| &ABILITIES[i])
}

/// One rank of one ability. `rank` is 1-based, exactly as a character's
/// `abilities` map stores it.
pub fn ability_rank(ability_uuid: &str, rank: u16) -> Option<&'static AbilityRank> {
    ability(ability_uuid)?.ranks().iter().find(|r| r.rank == rank)
}

/// One rank of one ability, clamped into the ranks that actually ship.
///
/// Gear and set bonuses can push an ability past its highest authored rank; the
/// client falls back to the last authored rank rather than losing the effect.
pub fn ability_rank_clamped(ability_uuid: &str, rank: u16) -> Option<&'static AbilityRank> {
    let ranks = ability(ability_uuid)?.ranks();
    if ranks.is_empty() {
        return None;
    }
    match ranks.iter().find(|r| r.rank == rank) {
        Some(r) => Some(r),
        None if rank == 0 => ranks.first(),
        None => ranks.last(),
    }
}

/// What drinking one consumable restores — 30 items.
///
/// Source: `RestorationAbility` (`dump.cs:606658`), whose fields are all
/// `[ExcelVariable]`, i.e. authored game data. Joined here from
/// `items.json` (the item NAME carries the pool and tier) against
/// `consumables.json` (the magnitudes, extracted from the APK's
/// `ConsumableEffectList`).
///
/// Only the three RESTORATION families are here. The other eleven
/// consumable families are alchemy effects (resists, weakness poisons)
/// carrying an `AlchemyInfo` rather than a restoration, and are not
/// modelled by this table.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Restoration {
    pub uuid: &'static str,
    /// `ActorStats.CoreStats`: 0 Health, 1 Stamina, 2 Magicka. Cross-checked
    /// at generation time against the pool named in the item's own name —
    /// a disagreement fails the build rather than shipping a potion that
    /// refills the wrong bar.
    pub affected_stat: u8,
    /// Flat amount restored. Every shipped tier is flat (`_restorationMode`
    /// 0); a percentage-mode tier is skipped at generation rather than
    /// applied as if it were flat.
    pub value: f32,
    /// Seconds the restoration is spread over. Uniformly 2.5 in the shipped
    /// data.
    pub duration: f32,
}

