/// What drinking `item_uuid` restores, or `None` if it restores nothing
/// (every non-restoration consumable, and any item at all).
pub fn restoration(item_uuid: &str) -> Option<&'static Restoration> {
    RESTORATIONS
        .binary_search_by(|r| r.uuid.cmp(item_uuid))
        .ok()
        .map(|i| &RESTORATIONS[i])
}

/// Enchantment family for a family UUID.
pub fn enchant_family(family_uuid: &str) -> Option<&'static EnchantFamily> {
    ENCHANT_FAMILIES
        .binary_search_by(|f| f.uuid.cmp(family_uuid))
        .ok()
        .map(|i| &ENCHANT_FAMILIES[i])
}

/// Magnitude of an `item.properties.ENCHANTING[{id, tier}]` entry.
pub fn enchant_value(family_uuid: &str, tier: u8) -> Option<f32> {
    enchant_family(family_uuid)?.value(tier)
}

/// Grade property for a GRADING affix UUID.
pub fn grade_property(uuid: &str) -> Option<&'static GradeProperty> {
    GRADE_PROPERTIES
        .binary_search_by(|g| g.uuid.cmp(uuid))
        .ok()
        .map(|i| &GRADE_PROPERTIES[i])
}

/// `_bonusValue` for one rank of a perk, e.g. `perk_bonus("ArmsmanPerk", 4)`.
///
/// `rank` is 1-based. `None` for an unknown perk or an out-of-range rank —
/// never a silent 0.0, because a zero here is indistinguishable from a perk
/// that genuinely does nothing, which is the bug this table exists to fix.
pub fn perk_bonus(perk: &str, rank: u8) -> Option<f32> {
    PERK_RANKS
        .binary_search_by(|p| p.perk.cmp(perk).then(p.rank.cmp(&rank)))
        .ok()
        .map(|i| PERK_RANKS[i].bonus_value)
}

/// Every rank of one perk, in rank order.
pub fn perk_ranks(perk: &str) -> impl Iterator<Item = &'static PerkRank> {
    PERK_RANKS.iter().filter(move |p| p.perk == perk)
}

