// ==========================================================================
// Conformance tests
// ==========================================================================
//
// These are the guard rails for "the combat model runs on the real numbers".
// The anchor literals are transcribed by hand from the source assets, NOT
// derived from the tables above, so a regeneration that moves a number fails
// here instead of silently changing how the fight plays.
#[cfg(test)]
mod tests {
    use super::*;

    // ---------------------------------------------------------------- anchors
    //
    // Hand-transcribed ground truth.
    //   WardRank1.asset      : _wardDuration 3, _wardHealth 120.54, _wardArmor 67.2
    //   ParalyzeRank1.asset  : _damage 88.7, _duration 2, _damageToCauseParalyze 32.7
    //   FireballRank1.asset  : _damage 73.89, _channelDuration 0.9
    //   ResistElementsRank1  : _resistanceAmount 48.54, _resistanceDuration 10,
    //                          _resistancesToAdd [4,5,6,7]
    //   combat_params.json   : the reduction caps + elemental_status_data

    /// `WardRank1._wardHealth`.
    pub const WARD_HEALTH_R1: f32 = 120.54;
    /// `WardRank1._wardArmor`.
    pub const WARD_ARMOR_R1: f32 = 67.2;
    /// `WardRank1._wardDuration` — **3 seconds**, not 60. The pre-gamedata model
    /// was 20x off here.
    pub const WARD_DURATION_R1: f32 = 3.0;
    /// `ParalyzeRank1._damageToCauseParalyze` — **32.7**, not ~1400. The
    /// pre-gamedata model was ~43x off here.
    pub const PARALYZE_DAMAGE_TO_CAUSE_R1: f32 = 32.7;
    /// `elemental_status_data[Poison].percent_health_damage`.
    pub const POISON_PCT_HEALTH: f32 = 0.02;
    /// `elemental_status_data[Frost].percent_health_damage` — **zero**. Frost
    /// drains Stamina; it does not tick health.
    pub const FROST_PCT_HEALTH: f32 = 0.0;
    /// `CombatParameters.maximumBlockReduction`.
    pub const MAX_BLOCK_REDUCTION: f32 = 0.95;
    /// `CombatParameters.maximumArmorReduction`.
    pub const MAX_ARMOR_REDUCTION: f32 = 0.95;

    #[test]
    fn ward_rank1_matches_the_shipped_asset() {
        let r = ability_rank(ids::WARD, 1).expect("Ward rank 1");
        assert_eq!(r.asset, "WardRank1");
        assert_eq!(r.ward_health(), Some(WARD_HEALTH_R1));
        assert_eq!(r.ward_armor(), Some(WARD_ARMOR_R1));
        assert_eq!(r.ward_duration(), Some(WARD_DURATION_R1));
        // Ward is a spell: it costs magicka and has a cooldown.
        assert_eq!(r.magicka_cost, Some(205.0));
        assert_eq!(r.cooldown, Some(7.5));
    }

    #[test]
    fn paralyze_rank1_matches_the_shipped_asset() {
        let r = ability_rank(ids::PARALYZE, 1).expect("Paralyze rank 1");
        assert_eq!(r.asset, "ParalyzeRank1");
        assert_eq!(
            r.damage_to_cause_paralyze(),
            Some(PARALYZE_DAMAGE_TO_CAUSE_R1)
        );
        assert_eq!(r.damage(), Some(88.7));
        assert_eq!(r.duration(), Some(2.0));
        assert_eq!(r.channel_duration(), Some(1.5));
    }

    #[test]
    fn fireball_and_resist_elements_rank1_match_the_shipped_assets() {
        let f = ability_rank(ids::FIREBALL, 1).expect("Fireball rank 1");
        assert_eq!(f.damage(), Some(73.89));
        assert_eq!(f.channel_duration(), Some(0.9));
        assert_eq!(f.projectile_speed(), Some(15.0));

        let r = ability_rank(ids::RESIST_ELEMENTS, 1).expect("ResistElements rank 1");
        assert_eq!(r.resistance_amount(), Some(48.54));
        assert_eq!(r.resistance_duration(), Some(10.0));
        // 4 = Fire, 5 = Frost, 6 = Shock, 7 = Poison.
        assert_eq!(r.resistances_to_add, &[4, 5, 6, 7]);
    }

    #[test]
    fn damage_reduction_caps_match_combat_parameters() {
        assert_eq!(combat_params::MAXIMUM_BLOCK_REDUCTION, MAX_BLOCK_REDUCTION);
        assert_eq!(combat_params::MAXIMUM_ARMOR_REDUCTION, MAX_ARMOR_REDUCTION);
        assert_eq!(combat_params::MAXIMUM_RESISTANCE_REDUCTION, 0.95);
        assert_eq!(combat_params::REDUCTION_PER_ARMOR_RATING, 0.1);
        assert_eq!(combat_params::REDUCTION_PER_RESISTANCE_RATING, 1.0);
        assert_eq!(combat_params::REDUCTION_PER_BLOCK_RATING, 0.1);
        assert_eq!(combat_params::PHYSICAL_BLOCK_RATING_FACTOR, 1.0);
        assert_eq!(combat_params::ELEMENTAL_BLOCK_RATING_FACTOR, 0.6666667);
        assert_eq!(combat_params::MINIMUM_BLOCK_REDUCTION, 0.0);
    }

    #[test]
    fn timing_and_threshold_params_match_combat_parameters() {
        assert_eq!(combat_params::POST_OPTIMAL_BLOCK_RESET_TIME, 1.4);
        assert_eq!(combat_params::BASE_STAGGER_DURATION, 1.5);
        assert_eq!(combat_params::CRITICAL_HEALTH_THRESHOLD, 35.0);
        assert_eq!(combat_params::CONSUMABLES_PER_ROUND, 1);
        assert_eq!(combat_params::GLOBAL_MINIMUM_ATTACK_DELAY, 0.1);
        assert_eq!(combat_params::GLOBAL_PVP_TICK_INTERVAL, 0.2);
        assert_eq!(combat_params::DAMAGE_INSTANCE_WINDOW, 5.0);
        assert_eq!(combat_params::FROST_DAMAGE_TO_STAMINA_DAMAGE, 1.0);
        assert_eq!(combat_params::SHOCK_DAMAGE_TO_MAGICKA_DAMAGE, 1.0);
    }

    #[test]
    fn continuous_damage_effectiveness_is_075_except_blocking() {
        for v in [
            combat_params::CONTINUOUS_DAMAGE_ABSORB_EFFECTIVENESS,
            combat_params::CONTINUOUS_DAMAGE_FORTIFY_EFFECTIVENESS,
            combat_params::CONTINUOUS_DAMAGE_RESISTANCE_EFFECTIVENESS,
            combat_params::CONTINUOUS_DAMAGE_REVENGE_EFFECTIVENESS,
            combat_params::CONTINUOUS_DAMAGE_WEAKNESS_EFFECTIVENESS,
        ] {
            assert_eq!(v, 0.75);
        }
        // Blocking is the exception — full effectiveness against DoT.
        assert_eq!(combat_params::CONTINUOUS_DAMAGE_BLOCKING_EFFECTIVENESS, 1.0);
    }

    #[test]
    fn elemental_dot_is_fire_and_poison_only() {
        assert_eq!(combat_params::FIRE_PCT_HEALTH, 0.02);
        assert_eq!(combat_params::POISON_PCT_HEALTH, POISON_PCT_HEALTH);
        assert_eq!(combat_params::FROST_PCT_HEALTH, FROST_PCT_HEALTH);
        assert_eq!(combat_params::SHOCK_PCT_HEALTH, 0.0);
        assert_eq!(combat_params::HEALTH_PERCENT_TO_CAUSE_STATUS, 0.25);
        assert_eq!(combat_params::ELEMENTAL_STATUS_DURATION, 5.0);

        for st in [4u8, 5, 6, 7] {
            let e = combat_params::elemental_status(st).expect("status row");
            assert_eq!(e.source_damage, st, "status_type == source_damage");
            assert_eq!(e.health_percent_to_cause_status, 0.25);
            assert_eq!(e.duration, 5.0);
        }
        assert_eq!(combat_params::elemental_status(1), None);
    }

    // ------------------------------------------------------------- item spot-check

    #[test]
    fn dragonbone_dagger_resolves_with_plausible_stats() {
        // The weapon Flappety carries in the s506 reference match: a Light,
        // Slashing, tier-10 dagger.
        let w = weapon(ids::DRAGONBONE_DAGGER).expect("Dragonbone Dagger");
        assert_eq!(w.name, "Dragonbone Dagger");
        assert_eq!(w.weapon_class, WeaponClass::Light);
        assert_eq!(w.weapon_type, WeaponType::Dagger);
        assert_eq!(w.damage_type, DamageType::Slashing);
        assert!(w.damage_type.is_physical());
        assert_eq!(w.base_damage, 99.0);
        assert_eq!(w.tier, 10);
        assert_eq!(w.required_level, 45);
        // Fastest class in the game, but still above the global floor.
        assert!(
            (0.23..0.24).contains(&w.attack_delay),
            "attack_delay {} out of range",
            w.attack_delay
        );
        assert!(w.attack_delay > combat_params::GLOBAL_MINIMUM_ATTACK_DELAY);
        assert!(
            (0.54..0.56).contains(&w.recovery_time),
            "recovery_time {} out of range",
            w.recovery_time
        );
        assert_eq!(w.block_base, 49.5);
        assert_eq!(block_base(ids::DRAGONBONE_DAGGER), Some(49.5));
    }

    #[test]
    fn armor_rating_only_resolves_for_armor_templates() {
        // A weapon uuid is not an armor uuid.
        assert_eq!(armor_rating(ids::DRAGONBONE_DAGGER), None);
        assert_eq!(armor_rating("not-a-uuid"), None);
        // Every armor row has a finite, non-negative rating.
        for a in ARMORS.iter() {
            assert!(
                a.armor_rating.is_finite() && a.armor_rating >= 0.0,
                "{} has armor_rating {}",
                a.name,
                a.armor_rating
            );
        }
        // …and at least one is a real, heavy end-game piece.
        assert!(ARMORS.iter().any(|a| a.armor_rating > 100.0));
    }

    #[test]
    fn enchant_values_resolve_by_family_and_tier() {
        let f = enchant_family(ids::WEAPON_FIRE_DAMAGE).expect("Weapon Fire Damage");
        assert_eq!(f.name, "Weapon Fire Damage");
        assert_eq!(f.logic, "WeaponDamageFirePropertyLogic");
        assert_eq!(f.affix_type, 2, "suffix");
        assert_eq!(enchant_value(ids::WEAPON_FIRE_DAMAGE, 10), Some(7591.0));
        assert_eq!(enchant_value(ids::WEAPON_FIRE_DAMAGE, 1), Some(268.0));
        // Tier numbers are sparse — tier 2 is not authored for this family.
        assert_eq!(enchant_value(ids::WEAPON_FIRE_DAMAGE, 2), None);
        assert_eq!(enchant_value("not-a-uuid", 1), None);
    }

    // ------------------------------------------------------------- table invariants

    #[test]
    fn tables_have_the_expected_shape() {
        assert_eq!(WEAPONS.len(), 370);
        assert_eq!(ARMORS.len(), 254);
        assert_eq!(SHIELDS.len(), 51);
        assert_eq!(ABILITIES.len(), 63);
        assert_eq!(ABILITY_RANKS.len(), 706);
        assert_eq!(ENCHANT_FAMILIES.len(), 116);
        assert_eq!(ENCHANT_TIERS.len(), 1094);
    }

    #[test]
    fn uuid_keyed_tables_are_sorted_and_unique() {
        fn check(name: &str, uuids: impl Iterator<Item = &'static str>) {
            let v: Vec<_> = uuids.collect();
            for pair in v.windows(2) {
                assert!(
                    pair[0] < pair[1],
                    "{name} is not strictly sorted by uuid: {} !< {} \
                     (binary_search lookups would be wrong)",
                    pair[0],
                    pair[1]
                );
            }
        }
        check("WEAPONS", WEAPONS.iter().map(|x| x.uuid));
        check("ARMORS", ARMORS.iter().map(|x| x.uuid));
        check("SHIELDS", SHIELDS.iter().map(|x| x.uuid));
        check("ABILITIES", ABILITIES.iter().map(|x| x.uuid));
        check("ENCHANT_FAMILIES", ENCHANT_FAMILIES.iter().map(|x| x.uuid));
    }

    #[test]
    fn every_row_is_reachable_through_its_lookup() {
        for x in WEAPONS.iter() {
            assert_eq!(weapon(x.uuid), Some(x), "weapon({})", x.uuid);
        }
        for x in ARMORS.iter() {
            assert_eq!(armor(x.uuid), Some(x), "armor({})", x.uuid);
        }
        for x in SHIELDS.iter() {
            assert_eq!(shield(x.uuid), Some(x), "shield({})", x.uuid);
        }
        for x in ENCHANT_FAMILIES.iter() {
            assert_eq!(enchant_family(x.uuid), Some(x));
        }
        assert_eq!(weapon("00000000-0000-0000-0000-000000000000"), None);
    }

    #[test]
    fn ability_rank_slices_are_consistent() {
        let mut seen = 0usize;
        for a in ABILITIES.iter() {
            let ranks = a.ranks();
            assert_eq!(
                ranks.len(),
                a.ranks_len as usize,
                "{} rank slice length",
                a.editor_name
            );
            assert_eq!(a.ranks_start as usize, seen, "{} rank slice offset", a.editor_name);
            seen += ranks.len();
            assert!(!ranks.is_empty(), "{} has no ranks", a.editor_name);
            for (i, r) in ranks.iter().enumerate() {
                assert_eq!(r.ability_uuid, a.uuid);
                assert_eq!(r.rank as usize, i + 1, "{} ranks are 1..n", a.editor_name);
                assert_eq!(ability_rank(a.uuid, r.rank), Some(r));
                // The sparse effect slice must stay sorted for `get`'s binary search.
                for pair in r.effects.windows(2) {
                    assert!(pair[0].0 < pair[1].0, "{} effects unsorted", r.asset);
                }
                for (f, v) in r.effects.iter() {
                    assert_eq!(r.get(*f), Some(*v));
                    assert!(v.is_finite(), "{}.{} is not finite", r.asset, f.name());
                }
            }
        }
        assert_eq!(seen, ABILITY_RANKS.len());
        assert_eq!(ability_rank(ids::WARD, 999), None);
        assert_eq!(ability_rank("not-a-uuid", 1), None);
    }

    #[test]
    fn ability_rank_clamped_saturates_at_the_last_authored_rank() {
        let last = ability(ids::WARD).unwrap().ranks().last().unwrap();
        assert_eq!(ability_rank_clamped(ids::WARD, 999), Some(last));
        assert_eq!(
            ability_rank_clamped(ids::WARD, 1),
            ability_rank(ids::WARD, 1)
        );
        assert_eq!(ability_rank_clamped("not-a-uuid", 1), None);
    }

    #[test]
    fn enchant_tier_slices_are_consistent() {
        let mut seen = 0usize;
        for f in ENCHANT_FAMILIES.iter() {
            assert_eq!(f.tiers_start as usize, seen, "{} tier offset", f.name);
            seen += f.tiers().len();
            for pair in f.tiers().windows(2) {
                assert!(pair[0].tier < pair[1].tier, "{} tiers unsorted", f.name);
            }
            for t in f.tiers() {
                assert_eq!(enchant_value(f.uuid, t.tier), Some(t.value));
            }
        }
        assert_eq!(seen, ENCHANT_TIERS.len());
    }

    #[test]
    fn damage_type_round_trips() {
        for raw in 0u8..=7 {
            let dt = DamageType::from_raw(raw).expect("known damage type");
            assert_eq!(dt.raw(), raw);
            assert_eq!(dt.is_physical(), (1..=3).contains(&raw));
            assert_eq!(dt.is_elemental(), (4..=7).contains(&raw));
        }
        assert_eq!(DamageType::from_raw(8), None);
        // Every weapon's class/type came back out of the raw enum intact.
        for w in WEAPONS.iter() {
            assert_eq!(WeaponClass::from_raw(w.weapon_class.raw()), Some(w.weapon_class));
            assert_eq!(WeaponType::from_raw(w.weapon_type.raw()), Some(w.weapon_type));
        }
    }

    // ------------------------------------------------------------- provenance

    /// The whole point of the sha256 gate: if someone re-runs an extractor and
    /// the shipped numbers move, this file must be regenerated too.
    ///
    /// Skipped (with a printed note) when the capture repo is not checked out
    /// next to the fork — CI boxes and contributors without it still build.
    #[test]
    fn source_hashes_match_the_committed_json() {
        use std::path::PathBuf;

        let roots = [
            PathBuf::from("/Users/berntsen/Projects/blades-capture/reference/game-defs"),
            PathBuf::from("../blades-capture/reference/game-defs"),
            PathBuf::from("../../blades-capture/reference/game-defs"),
        ];
        let Some(root) = roots.into_iter().find(|p| p.is_dir()) else {
            eprintln!("skip: blades-capture/reference/game-defs not found next to the fork");
            return;
        };

        for (file, expected) in source_hashes::ALL {
            let path = root.join(file);
            let Ok(bytes) = std::fs::read(&path) else {
                eprintln!("skip {file}: not readable at {}", path.display());
                continue;
            };
            let got = sha256_hex(&bytes);
            assert_eq!(
                &got, expected,
                "\n{} changed but gamedata.rs was not regenerated.\n\
                 Run: blades-capture/reference/game-defs/extract/gen_gamedata_rs.py\n",
                path.display()
            );
        }
    }

    /// Minimal SHA-256 — the crate has no hashing dependency and this module is
    /// deliberately a leaf, so the 40 lines live here rather than pulling one in.
    fn sha256_hex(data: &[u8]) -> String {
        const K: [u32; 64] = [
            0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4,
            0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe,
            0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f,
            0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7,
            0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc,
            0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b,
            0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116,
            0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
            0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7,
            0xc67178f2,
        ];
        let mut h: [u32; 8] = [
            0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab,
            0x5be0cd19,
        ];
        let mut msg = data.to_vec();
        let bit_len = (data.len() as u64) * 8;
        msg.push(0x80);
        while msg.len() % 64 != 56 {
            msg.push(0);
        }
        msg.extend_from_slice(&bit_len.to_be_bytes());

        for chunk in msg.chunks(64) {
            let mut w = [0u32; 64];
            for i in 0..16 {
                w[i] = u32::from_be_bytes([
                    chunk[i * 4],
                    chunk[i * 4 + 1],
                    chunk[i * 4 + 2],
                    chunk[i * 4 + 3],
                ]);
            }
            for i in 16..64 {
                let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
                let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
                w[i] = w[i - 16]
                    .wrapping_add(s0)
                    .wrapping_add(w[i - 7])
                    .wrapping_add(s1);
            }
            let (mut a, mut b, mut c, mut d, mut e, mut f, mut g, mut hh) =
                (h[0], h[1], h[2], h[3], h[4], h[5], h[6], h[7]);
            for i in 0..64 {
                let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
                let ch = (e & f) ^ ((!e) & g);
                let t1 = hh
                    .wrapping_add(s1)
                    .wrapping_add(ch)
                    .wrapping_add(K[i])
                    .wrapping_add(w[i]);
                let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
                let maj = (a & b) ^ (a & c) ^ (b & c);
                let t2 = s0.wrapping_add(maj);
                hh = g;
                g = f;
                f = e;
                e = d.wrapping_add(t1);
                d = c;
                c = b;
                b = a;
                a = t1.wrapping_add(t2);
            }
            h[0] = h[0].wrapping_add(a);
            h[1] = h[1].wrapping_add(b);
            h[2] = h[2].wrapping_add(c);
            h[3] = h[3].wrapping_add(d);
            h[4] = h[4].wrapping_add(e);
            h[5] = h[5].wrapping_add(f);
            h[6] = h[6].wrapping_add(g);
            h[7] = h[7].wrapping_add(hh);
        }
        h.iter().map(|v| format!("{v:08x}")).collect()
    }

    #[test]
    fn sha256_helper_is_correct() {
        assert_eq!(
            sha256_hex(b""),
            "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
        );
        assert_eq!(
            sha256_hex(b"abc"),
            "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"
        );
    }
}

